import subprocess, os, sys, json
env = dict(os.environ); env['TERM']='dumb'; env.pop('YQ_COLORS', None)

def run(args, stdin=b'', extra_env=None):
    e = dict(env)
    if extra_env: e.update(extra_env)
    p = subprocess.run(['/workspace/executable']+args, input=stdin, capture_output=True, env=e)
    return p.returncode, p.stdout.decode('utf-8','replace'), p.stderr.decode('utf-8','replace')

def show(label, args, stdin=b'', extra_env=None, w=34):
    rc, out, err = run(args, stdin, extra_env)
    s = repr(out)
    if err: s += '  ERR=' + repr(err.strip()[:120])
    if rc: s += '  rc=%d' % rc
    print('%-*s %s' % (w, label, s))

import subprocess, os, sys
env = dict(os.environ); env['TERM']='dumb'; env.pop('YQ_COLORS', None)

def run(args, stdin=b'', extra_env=None):
    e = dict(env)
    if extra_env: e.update(extra_env)
    p = subprocess.run(['/workspace/executable']+args, input=stdin, capture_output=True, env=e)
    return p.returncode, p.stdout.decode('utf-8','replace'), p.stderr.decode('utf-8','replace')

def emit(s):
    rc, out, err = run(['-n', '.a = strenv(V)'], extra_env={'V': s})
    if rc: return 'ERR:'+err.strip()
    assert out.startswith('a: '), repr(out)
    return out[3:].rstrip('\n')

def classify(s):
    o = emit(s)
    if o.startswith("'"): return 'single'
    if o.startswith('"'): return 'double'
    if o.startswith('|') or o.startswith('>'): return 'block'
    return 'plain'

results = {}
for i in range(0x20, 0x7f):
    c = chr(i)
    row = []
    for tmpl in ['%s', 'a%s', '%sa', 'a%sb', 'a %s', '%s a', 'a%s ']:
        row.append(classify(tmpl % c))
    results[c] = row
print('char  alone  a+c    c+a    acb    "a c" "c a"  "ac "')
for c, row in results.items():
    print('%-5s %s' % (repr(c), '  '.join('%-6s' % x for x in row)))

